/* @lc app=leetcode id=939 lang=kotlin */ class Solution { fun minAreaRect(points: Array<IntArray>): Int = points.map { it[0] * 40001 + it[1] }.toSet().let { s -> points.indices.flatMap { i -> (i + 1 until points.size).filter { j -> points[i][0] != points[j][0] && points[i][1] != points[j][1] && (points[i][0] * 40001 + points[j][1]) in s && (points[j][0] * 40001 + points[i][1]) in s }.map { j -> Math.abs(points[i][0] - points[j][0]) * Math.abs(points[i][1] - points[j][1]) } }.minOrNull() ?: 0 } }